package keystrokesmod.script.packet.serverbound;
import keystrokesmod.script.model.ItemStack; import keystrokesmod.script.model.Vec3; import net.minecraft.network.play.client.C08PacketPlayerBlockPlacement;
public class C08 extends CPacket { public ItemStack itemStack; public Vec3 position,offset; public int direction; public C08(ItemStack item,Vec3 pos,int direction,Vec3 offset){super(new C08PacketPlayerBlockPlacement(Vec3.getBlockPos(pos),direction,item==null?null:item.itemStack,(float)offset.x,(float)offset.y,(float)offset.z));itemStack=item;position=pos;this.direction=direction;this.offset=offset;} public C08(C08PacketPlayerBlockPlacement value){super(value);itemStack=ItemStack.convert(value.getStack());position=new Vec3(value.getPosition());direction=value.getPlacedBlockDirection();offset=new Vec3(value.getPlacedBlockOffsetX(),value.getPlacedBlockOffsetY(),value.getPlacedBlockOffsetZ());} public C08PacketPlayerBlockPlacement convert(){return (C08PacketPlayerBlockPlacement)packet;} }
